import Foundation

/// The pinned model files, generated by
/// `clients/apps/electron/scripts/transcriber-models-manifest.ts` and compiled
/// into the helper. An install is accepted only when it matches this list.
public struct ModelManifest: Decodable, Sendable, Equatable {
    public struct Repo: Decodable, Sendable, Equatable {
        public let repo: String
        public let revision: String
        /// FluidAudio's `Repo.folderName` under the models root.
        public let folder: String
        /// `ModelHub.download` variant.
        public let variant: String
    }

    public struct File: Decodable, Sendable, Equatable {
        public let path: String
        public let size: Int64
        public let sha256: String

        public init(path: String, size: Int64, sha256: String) {
            self.path = path
            self.size = size
            self.sha256 = sha256
        }
    }

    /// Name of the installed folder under the models directory.
    public let id: String
    public let repos: [Repo]
    public let files: [File]

    public init(id: String, repos: [Repo], files: [File]) {
        self.id = id
        self.repos = repos
        self.files = files
    }

    public var totalBytes: Int64 { files.reduce(0) { $0 + $1.size } }

    public static func bundled() throws -> ModelManifest {
        try JSONDecoder().decode(ModelManifest.self, from: Data(PackageResources.models_manifest_json))
    }
}
